<?php
session_start(); require_once '../conexion.php';
if(!isset($_SESSION['usuario_id'])||$_SESSION['rol']!=='admin'){header('Location: ../login.php');exit;}
$error=''; $categorias=$conexion->query("SELECT id_categoria,nombre FROM Categoria ORDER BY nombre"); $ubicaciones=$conexion->query("SELECT id_ubicacion,pasillo,estante,posicion FROM Ubicacion ORDER BY pasillo,estante,posicion");
if($_SERVER['REQUEST_METHOD']==='POST'){$nombre=trim($_POST['nombre']??'');$descripcion=trim($_POST['descripcion']??'');$stock=(int)($_POST['stock']??0);$stock_minimo=(int)($_POST['stock_minimo']??0);$cat=(int)($_POST['id_categoria']??0);$ubi=(int)($_POST['id_ubicacion']??0);if($nombre===''||$stock<0||$stock_minimo<0||$cat<=0||$ubi<=0)$error='Completá correctamente todos los campos.';else{$estado='Disponible';$stmt=$conexion->prepare("INSERT INTO Producto (Nombre,descripcion,stock_actual,stock_minimo,estado_producto,id_categoria,id_ubicacion) VALUES (?,?,?,?,?,?,?)");$stmt->bind_param('ssiiiii',$nombre,$descripcion,$stock,$stock_minimo,$estado,$cat,$ubi);if($stmt->execute()){header('Location: productos.php?mensaje='.urlencode('Producto agregado correctamente.'));exit;}$error='No se pudo guardar: '.$stmt->error;}}
?><!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Agregar producto | Softyle</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.2/dist/css/bootstrap.min.css" rel="stylesheet"><link rel="stylesheet" href="../CSS/sistema.css"></head><body class="sistema-body"><main class="admin-container"><a href="productos.php" class="volver-link">← Volver a productos</a><section class="dashboard-header"><span class="dashboard-label">INVENTARIO</span><h1>Agregar producto</h1></section><?php if($error):?><div class="alert alert-danger"><?=htmlspecialchars($error)?></div><?php endif;?><div class="form-sistema-card"><form method="POST"><div class="mb-3"><label>Nombre</label><input name="nombre" class="form-control" required></div><div class="mb-3"><label>Descripción</label><input name="descripcion" class="form-control"></div><div class="mb-3"><label>Stock actual</label><input type="number" name="stock" min="0" value="0" class="form-control" required></div><div class="mb-3"><label>Stock mínimo</label><input type="number" name="stock_minimo" min="0" value="0" class="form-control" required></div><div class="mb-3"><label>Categoría</label><select name="id_categoria" class="form-select" required><?php while($x=$categorias->fetch_assoc()):?><option value="<?=$x['id_categoria']?>"><?=htmlspecialchars($x['nombre'])?></option><?php endwhile;?></select></div><div class="mb-4"><label>Ubicación</label><select name="id_ubicacion" class="form-select" required><?php while($x=$ubicaciones->fetch_assoc()):?><option value="<?=$x['id_ubicacion']?>"><?=htmlspecialchars($x['pasillo'].'-'.$x['estante'].'-'.$x['posicion'])?></option><?php endwhile;?></select></div><button class="btn-picking">Guardar producto</button></form></div></main></body></html>